"""Generate the UI graphics registry data from the repository-owned contract."""
from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "schema" / "graphics.registry.json"
TARGET = ROOT / "ui" / "src" / "graphics" / "registry.data.ts"


def render() -> str:
    contract = json.loads(SOURCE.read_text(encoding="utf-8"))
    return (
        "/* This file is generated by scripts/export_graphics_registry.py. */\n"
        "/* Do not edit directly; update schema/graphics.registry.json. */\n"
        f"export const GRAPHIC_REGISTRY_GEOMETRY = {json.dumps(contract['geometry'], indent=2)} as const;\n"
        f"export const GRAPHIC_REGISTRY_MOTION = {json.dumps(contract['motion'], indent=2)} as const;\n"
        f"export const GRAPHIC_REGISTRY_CONTRACT = {json.dumps(contract['components'], indent=2)} as const;\n"
    )


def main() -> None:
    TARGET.write_text(render(), encoding="utf-8", newline="\n")
    print(f"wrote {TARGET}")


if __name__ == "__main__":
    main()
